const normalize=s=>String(s||'').trim().toLowerCase().replace(/\s+/g,' ');
const summary={imported:questions.length,added:0,existing:0,missing:[],figureDependent:0};
for(const q of questions){
 const section=lesson.sections?.find(s=>s.title===q.topic);
 if(!section){summary.missing.push(q.id+': '+q.topic);continue;}
 const front=q.prompt+'\n'+q.options.map((o,j)=>String.fromCharCode(65+j)+'. '+o).join('\n')+(q.needsFigure?'\n[Referenced lecture figure'+(q.slide?', slide '+q.slide:'')+' — review the original slide]':'');
 const back=String.fromCharCode(65+q.correctIndex)+'. '+q.answer;
 section.flashcards=section.flashcards||[];
 if(!section.flashcards.some(([p])=>normalize(p)===normalize(front))){section.flashcards.push([front,back]);summary.added++;}else summary.existing++;
 section.practiceQuestions=section.practiceQuestions||[];
 if(!section.practiceQuestions.some(x=>x.id===q.id))section.practiceQuestions.push(q);
 if(q.needsFigure)summary.figureDependent++;
}
window.VPQ_PATH_L68_USER_MCQ=summary;
